import { Object3D, PlaneGeometry, Mesh, Color } from 'three/webgpu';
import { texture } from 'three/tsl';
import { MeshBasicNodeMaterial } from 'three/webgpu';
import { gsap } from 'gsap';
import '@/primitives';
import '@/text';

/**
 * @typedef {Object} NodeConfig
 * @property {{imageUrl:string}} assets
 * @property {{ink:string, paper:string, accent:string, surface:string}} visual
 * @property {{textContent:string}} textContent
 * @property {{position: [number, number, number], rotation: [number, number, number], scale: [number, number, number]}} placement
 * @property {Array<{name:string, params:any}>} cinematicPrimitives
 *
 * @typedef {Object} NodeContext
 * @property {{load: (url:string)=>THREE.Texture}} textureLoader
 * @property {{createText: (options:any)=>THREE.Object3D}} fontAtlas
 * @property {{primitives: Record<string, (obj:THREE.Object3D, params:any)=>void>}} primitives
 */

/**
 * Creates a Pricing title node.
 * @param {NodeConfig} config
 * @param {NodeContext} ctx
 * @returns {THREE.Object3D}
 */
export default function createNode(config, ctx) {
	// Root container
	const root = new Object3D();
	root.position.fromArray(config.placement?.position ?? [0, 0, 0]);
	root.rotation.fromArray(config.placement?.rotation ?? [0, 0, 0]);
	root.scale.fromArray(config.placement?.scale ?? [1, 1, 1]);

	// -----------------------------------------------------------------
	// Textured plane
	// -----------------------------------------------------------------
	const tex = ctx.textureLoader.load(config.assets?.imageUrl);
	const srcRect = config.atlasRegion?.sourceRect ?? [0, 0, 512, 320];
	const aspect = srcRect[2] / srcRect[3]; // width / height

	const geometry = new PlaneGeometry(aspect, 1);
	const mapNode = texture(tex);
	const material = new MeshBasicNodeMaterial({
		map: mapNode,
		transparent: true,
		depthTest: true,
	});

	const plane = new Mesh(geometry, material);
	plane.matrixAutoUpdate = false;
	plane.updateMatrix();

	root.add(plane);

	// -----------------------------------------------------------------
	// MSDF text
	// -----------------------------------------------------------------
	if (config.textContent) {
		const textMesh = ctx.fontAtlas.createText({
			text: config.textContent,
			font: 'display',
			size: 0.96, // approximate scene‑unit height for 96 px headline
			color: new Color(config.visual?.ink ?? '#16161d'),
			atlasIndex: config.atlasRegion?.atlas ?? 0,
			sourceRect: srcRect,
			// align centre on the plane
			anchor: [0, 0],
		});
		// Position text slightly in front of the plane to avoid z‑fighting
		textMesh.position.set(0, 0, 0.001);
		root.add(textMesh);
	}

	// -----------------------------------------------------------------
	// Apply cinematic primitives (if any)
	// -----------------------------------------------------------------
	if (Array.isArray(config.cinematicPrimitives)) {
		for (const prim of config.cinematicPrimitives) {
			if (ctx.primitives[prim.name]) {
				ctx.primitives[prim.name](root, prim.params);
			}
		}
	}

	// -----------------------------------------------------------------
	// User data – handlers placeholder and cleanup
	// -----------------------------------------------------------------
	root.userData.handlers = {};

	const timelines = [];

	root.userData.cleanup = () => {
		// Dispose material and texture
		material.dispose();
		tex.dispose();

		// Dispose geometry
		geometry.dispose();

		// Dispose any child objects (e.g., text mesh)
		root.traverse((obj) => {
			if (obj.geometry) obj.geometry.dispose();
			if (obj.material) obj.material.dispose();
		});

		// Kill GSAP timelines
		for (const tl of timelines) {
			if (tl.kill) tl.kill();
		}
	};

	return root;
}
